function p6_surrender(PDO $pdo,array &$ids,int $site,int $owner,string $status,float $quantity,string $unit='L'):int{$code='P6-'.strtoupper(bin2hex(random_bytes(6)));$q=$pdo->prepare('INSERT INTO oil_surrenders(transaction_code,establishment_id,submitted_by,surrendered_at,oil_quantity,oil_unit,status,approved_at)VALUES(?,?,?,UTC_TIMESTAMP(),?,?,?,IF(?=\'APPROVED\',UTC_TIMESTAMP(),NULL))');$q->execute([$code,$site,$owner,$quantity,$unit,$status,$status]);$id=(int)$pdo->lastInsertId();$ids['surrenders'][]=$id;return$id;}
function p6_token(PDO$pdo,int$userId,string$hash):string{$token=bin2hex(random_bytes(32));$pdo->prepare('INSERT INTO mobile_tokens(user_id,token_hash,password_fingerprint,expires_at)VALUES(?,?,?,DATE_ADD(UTC_TIMESTAMP(),INTERVAL 1 HOUR))')->execute([$userId,hash('sha256',$token),hash('sha256',$hash)]);return$token;}
function p6_api(string$method,string$path,?string$token):array{global$base;$c=curl_init($base.$path);$headers=[];if($token)$headers[]='Authorization: Bearer '.$token;curl_setopt_array($c,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>15,CURLOPT_CUSTOMREQUEST=>$method,CURLOPT_HTTPHEADER=>$headers]);$raw=curl_exec($c);if($raw===false)throw new RuntimeException(curl_error($c));$result=['status'=>curl_getinfo($c,CURLINFO_RESPONSE_CODE),'json'=>json_decode($raw,true)];curl_close($c);return$result;}
function p6_login(string$email,string$password):CurlHandle{global$base;$c=curl_init();curl_setopt_array($c,[CURLOPT_URL=>$base.'/public/login.php',CURLOPT_RETURNTRANSFER=>true,CURLOPT_HEADER=>true,CURLOPT_COOKIEFILE=>'',CURLOPT_FOLLOWLOCATION=>false]);$raw=curl_exec($c);$size=curl_getinfo($c,CURLINFO_HEADER_SIZE);preg_match('/name="csrf_token" value="([a-f0-9]{64})"/',substr($raw,$size),$m);curl_setopt_array($c,[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>http_build_query(['csrf_token'=>$m[1]??'','email'=>$email,'password'=>$password]),CURLOPT_HTTPHEADER=>['Content-Type: application/x-www-form-urlencoded']]);curl_exec($c);if(curl_getinfo($c,CURLINFO_RESPONSE_CODE)!==303)throw new RuntimeException('Phase 6 staff login failed.');curl_setopt_array($c,[CURLOPT_POST=>false,CURLOPT_CUSTOMREQUEST=>'GET',CURLOPT_HEADER=>false]);return$c;}
