 $ruleInput['rice_reward_quantity']=3;$ruleInput['name']='DEVELOPMENT TEST DATA: revised';phase6_save_rule($pdo,$ruleInput,$ids['users']['administrator'],$rule);$snapshot=phase6_incentive_record($pdo,$record['id']);p6_check((float)$snapshot['rule_reward_snapshot']===2.0&&(float)$snapshot['rice_quantity']===4.0,'Historical calculation snapshot survives rule edits');
