 $distributed=phase6_distribute($pdo,$record['id'],$ids['users']['administrator'],0,'Phase 6 TEST DATA distribution');p6_check($distributed['status']==='DISTRIBUTED'&&(int)$distributed['distributed_by']===$ids['users']['administrator']&&$distributed['distributed_at']!==null,'Distribution records status, user, and time');p6_expect(Phase6ConflictException::class,fn()=>phase6_distribute($pdo,$record['id'],$ids['users']['administrator'],1,''),'Distributed reward cannot be reversed or redistributed');
